{"path": "hangman.py", "content": "# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'

MAX_FAILURES = 9


class Hangman:
    """Hangman whose state is derived from the stream of guesses.

    The only stored input is the sequence of guesses; remaining guesses,
    masked word and status are all computed from it.
    """

    def __init__(self, word):
        self.word = word
        self.guesses = []
        self.remaining_guesses = MAX_FAILURES
        self.status = STATUS_ONGOING

    def _failures(self):
        seen = set()
        failures = 0
        for char in self.guesses:
            if char in seen or char not in self.word:
                failures += 1
            seen.add(char)
        return failures

    def _derive(self):
        self.remaining_guesses = MAX_FAILURES - self._failures()
        if set(self.word) <= set(self.guesses):
            self.status = STATUS_WIN
        elif self.remaining_guesses < 0:
            self.status = STATUS_LOSE
        else:
            self.status = STATUS_ONGOING

    def guess(self, char):
        if self.status != STATUS_ONGOING:
            raise ValueError('The game has already ended.')
        self.guesses.append(char)
        self._derive()

    def get_masked_word(self):
        guessed = set(self.guesses)
        return ''.join(c if c in guessed else '_' for c in self.word)

    def get_status(self):
        return self.status
